import{_ as a,o as e,c as o,a2 as s}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"クイックスタート","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/quick-start.md","filePath":"ja/guides/quick-start.md","lastUpdated":1792323081000}'),r={name:"ja/guides/quick-start.md"};function n(l,t,i,h,d,p){return e(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="クイックスタート" tabindex="-1">クイックスタート <a class="header-anchor" href="#クイックスタート" aria-label="Permalink to &quot;クイックスタート&quot;">​</a></h1><p>ゼロから始める完全チュートリアルです。アプリをインストールし、サインインして最初の Bot を作成し、実際の仕事を任せ、チャットプラットフォームから使えるようにします。所要時間は約 15 分です。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>macOS、Windows または Linux のコンピューター。</li><li><a href="https://app.memoh.net" target="_blank" rel="noreferrer">Memoh Cloud</a> のアカウント。サインイン時にそのまま登録できます。</li></ul><p>必要なのはこれだけです。Memoh Cloud にはホスト済みモデル（DeepSeek、Kimi、GPT、Claude など）が組み込まれているので、始めるのに API Key は一切要りません。</p><h2 id="ステップ-1-memoh-をインストールする" tabindex="-1">ステップ 1：Memoh をインストールする <a class="header-anchor" href="#ステップ-1-memoh-をインストールする" aria-label="Permalink to &quot;ステップ 1：Memoh をインストールする&quot;">​</a></h2><p><a href="https://memoh.ai/desktop" target="_blank" rel="noreferrer">ダウンロードページ</a> からお使いのプラットフォーム向けのパッケージ（macOS は DMG、Windows はインストーラー、Linux は AppImage/deb/rpm）をダウンロードして開きます。</p><h2 id="ステップ-2-サインインする" tabindex="-1">ステップ 2：サインインする <a class="header-anchor" href="#ステップ-2-サインインする" aria-label="Permalink to &quot;ステップ 2：サインインする&quot;">​</a></h2><p>接続画面で <strong>Memoh Cloud</strong> を選んでサインインします。アカウントがなければ、先に登録してください。</p><h2 id="ステップ-3-最初の-bot-を作成する" tabindex="-1">ステップ 3：最初の Bot を作成する <a class="header-anchor" href="#ステップ-3-最初の-bot-を作成する" aria-label="Permalink to &quot;ステップ 3：最初の Bot を作成する&quot;">​</a></h2><p><strong>Bot → 新しい Bot</strong> に進み、名前と表示名を入力して、<strong>一般</strong> タブで会話モデルを選びます。ホスト済みモデルはそのまま使えます。</p><p>次に Bot への指示を書きます。このステップが最も重要で、最もつまずきやすいところです。失敗の多くは、書き方が漠然としすぎていることにあります。1 つの仕事をはっきり伝えましょう。</p><blockquote><p><strong>名前：</strong> Digest</p><p><strong>役割：</strong> 週次のリーディングダイジェスト</p><p><strong>指示：</strong> 私がこの 1 週間に送った記事を集めてください。毎週金曜日に、テーマごとにグループ化したダイジェストにまとめます。各記事は 1 文で要約して元のリンクを添え、最後に「もう一度読む価値あり」のセクションを付けてください。元のリンクは変更しないこと。いかなる内容も公開しないこと。</p></blockquote><p>役割を 1 つに絞った Bot は、何でも屋の Bot よりはるかに多くの有効なコンテキストを蓄積できます。仕事が本当に別々の役割に分かれるときは、この Bot に積み増すのではなく、新しい Bot を作ってください。各 Bot は専用のワークスペース、メモリ、設定を持ちます。タブごとの説明は <a href="./working-with-bots.html">Bot</a> を参照してください。</p><p><strong>チャット</strong> をクリックして挨拶してみましょう。返事が来れば、モデルへの経路は通っています。</p><h2 id="自分のモデルを使う-byok" tabindex="-1">自分のモデルを使う（BYOK） <a class="header-anchor" href="#自分のモデルを使う-byok" aria-label="Permalink to &quot;自分のモデルを使う（BYOK）&quot;">​</a></h2><p>ホスト済みモデルとは別に、いつでも自分のモデルを持ち込めます（Bring Your Own Key）。</p><ol><li>サイドバーで <strong>プロバイダー</strong> を開き、<strong>プロバイダーを追加</strong> をクリックします。</li><li>テンプレート（OpenAI、Anthropic、Gemini、DeepSeek、Zhipu、OpenRouter、Ollama など）を選んで API Key を入力します。OpenAI 互換エンドポイントの場合は、対応する Base URL も入力してください。</li><li>そのプロバイダーを開いてモデル一覧を<strong>同期</strong>するか、会話モデルを少なくとも 1 つ手動で追加し、Bot の <strong>一般</strong> タブでそのモデルに切り替えます。</li></ol><p>BYOK のモデル使用量は、選んだプロバイダーの料金で課金されます。コーディングエージェントも同じ考え方です。Bot の <strong>エージェント</strong> タブで、自分のサブスクリプションまたは API Key を使って Claude Code や Codex にサインインしてください。プロバイダーごとのフィールドと注意点は <a href="./../integrations/providers/llm.html">モデルプロバイダー</a> にあります。</p><h2 id="ステップ-4-最初のタスクを任せる" tabindex="-1">ステップ 4：最初のタスクを任せる <a class="header-anchor" href="#ステップ-4-最初のタスクを任せる" aria-label="Permalink to &quot;ステップ 4：最初のタスクを任せる&quot;">​</a></h2><p>良い最初の依頼は、次の 5 つの問いに答えています。</p><table tabindex="0"><thead><tr><th>要素</th><th>答える問い</th></tr></thead><tbody><tr><td><strong>結果</strong></td><td>終わったとき、何が存在しているべきか？</td></tr><tr><td><strong>ソース</strong></td><td>どのファイル・サイト・会話が関係するか？</td></tr><tr><td><strong>制約</strong></td><td>何に触れてはいけないか、何にあなたの承認が要るか？</td></tr><tr><td><strong>形式</strong></td><td>結果はどんな形で届けるか？</td></tr><tr><td><strong>確認ポイント</strong></td><td>いつ手を止めてあなたに確認すべきか？</td></tr></tbody></table><p>外部へのログインなしに数分で結果を見たいなら、ドキュメントを 1 つアップロードして試してみてください。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>このドキュメントを 5 つの要点に要約してください。別のセクションに、文中のすべての日付・決定事項・</span></span>
<span class="line"><span>未解決の課題を列挙し、それぞれがどのページまたはどのセクションに由来するかを記してください。</span></span>
<span class="line"><span>元のファイルは変更しないでください。</span></span></code></pre></div><p>Bot は自分のワークスペースの中でファイルを読み、結果を会話に書き戻します。Bot が生み出したものはすべてワークスペースに残り、<a href="./files.html">ファイル</a> から閲覧・編集できます。</p><h2 id="ステップ-5-ワークスペースとブラウザを使わせる" tabindex="-1">ステップ 5：ワークスペースとブラウザを使わせる <a class="header-anchor" href="#ステップ-5-ワークスペースとブラウザを使わせる" aria-label="Permalink to &quot;ステップ 5：ワークスペースとブラウザを使わせる&quot;">​</a></h2><p>ワークスペースは Bot が仕事をする場所です。Linux ファイルシステム、ターミナル、プリインストール済みのツールチェーン（Python、Node.js、uv、npm）を備えており、データクリーニングもスクリプトもビルドもそのまま実行できます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>さっきアップロードした CSV から、email 列が空の行をすべて削除してください。</span></span>
<span class="line"><span>クリーニング後のファイルを渡して、何行削除したかを教えてください。</span></span></code></pre></div><p>タスクに本物のブラウザが必要なとき（headless モードでは動かないサイトや、ログインしないと見られないページなど）は、Bot の <strong>Desktop</strong> タブで可視デスクトップを有効にします。起動すると Bot はヘッド付き Chrome を操作し、あなたはデスクトップパネルでその様子を見守れます。</p><p>ログインの壁にぶつかったら、自分で画面を引き継ぎましょう。パスワード、パスキー、またはワンタイムコードを入力してから、操作を Bot に返します。ブラウザセッションはそのワークスペースに保持されるため、以降のタスクでもログイン状態は続きます。</p><div class="warning custom-block"><p class="custom-block-title">権限は必要な分だけ</p><p>ワークスペースの権限は段階制です。チャットのみ、ファイルの読み取り、ファイルの書き込み、コマンドの実行、コンテナの管理。タスクに必要なレベルだけを与え、それ以上は与えないでください。<a href="./access.html">アクセス制御</a> を参照してください。</p></div><p>詳しくは <a href="./container.html">ワークスペース</a> と <a href="./browser-computer-use.html">Browser / Computer Use</a> を参照してください。</p><h2 id="ステップ-6-チャットプラットフォームから使う" tabindex="-1">ステップ 6：チャットプラットフォームから使う <a class="header-anchor" href="#ステップ-6-チャットプラットフォームから使う" aria-label="Permalink to &quot;ステップ 6：チャットプラットフォームから使う&quot;">​</a></h2><p>Bot が最も役に立つのは、あなたが普段からチャットしている場所です。</p><ol><li>Bot の <strong>プラットフォーム</strong> タブを開き、<strong>追加</strong> をクリックします。</li><li>プラットフォーム（Telegram、Slack、Discord、Feishu、DingTalk、WeCom、WeChat、QQ、LINE）を選び、そのプラットフォームの資格情報を入力します。</li><li>そのプラットフォームから Bot にメッセージを送ります。最初のメッセージでセッションが作成されます。<code>/help</code> を送ると、使える <a href="./slash-commands.html">スラッシュコマンド</a> を確認できます。</li></ol><p>これで、スマートフォンから仕事を任せて、同じ会話で結果を受け取れるようになります。プラットフォームごとの設定は <a href="./../integrations/channels/">チャネル</a> を参照してください。</p><h2 id="ステップ-7-振り返って定着させる" tabindex="-1">ステップ 7：振り返って定着させる <a class="header-anchor" href="#ステップ-7-振り返って定着させる" aria-label="Permalink to &quot;ステップ 7：振り返って定着させる&quot;">​</a></h2><p>何かが違ったら、そのまま伝えましょう。修正はその場かぎりの手直しではなく、長く効くルールとして言い換えます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>今後のすべてのダイジェストはこの形式で：テーマごとにグループ化し、各記事 1 行、</span></span>
<span class="line"><span>リンクは行内に入れ、最後に「もう一度読む価値あり」のセクションを付ける。</span></span></code></pre></div><p>一連の流れが安定したら、毎回入力し直すのはやめましょう。</p><ul><li><a href="./skills.html">スキル</a> として保存すれば、以後は一言で手順一式を呼び出せます。</li><li><a href="./schedule.html">スケジュールタスク</a> にすれば、チャットなしで cron に従って自動実行されます。</li><li><a href="./memory.html">長期メモリ</a> を使えば、好みやプロジェクトのコンテキストがその後のすべてのセッションに引き継がれます。</li></ul><h2 id="次のステップ" tabindex="-1">次のステップ <a class="header-anchor" href="#次のステップ" aria-label="Permalink to &quot;次のステップ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>読むページ</th></tr></thead><tbody><tr><td>Bot をタブごとに設定する</td><td><a href="./working-with-bots.html">Bot</a></td></tr><tr><td>chat と discuss、メッセージルーティングを理解する</td><td><a href="./sessions.html">セッション</a></td></tr><tr><td>スケジュール実行や定期タスクを動かす</td><td><a href="./schedule.html">スケジュールタスク</a></td></tr><tr><td>外部のツールやデータに接続する</td><td><a href="./mcp.html">MCP</a>、<a href="./../self-hosted/connectors.html">コネクター</a></td></tr><tr><td>出来合いの機能をインストールする</td><td><a href="./supermarket.html">マーケットプレイス</a></td></tr><tr><td>ライフサイクルの節目に独自のロジックを差し込む</td><td><a href="./hooks.html">Hooks</a></td></tr><tr><td>誰が Bot と話せるかを制御する</td><td><a href="./access.html">アクセス制御</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">ヘルプが必要ですか？</p><p>サブスクリプション、credits、アカウントに関する質問や、このドキュメントで扱っていない疑問は、<a href="https://memoh.ai/help" target="_blank" rel="noreferrer">ヘルプセンター</a> で答えが見つかります。そこから Memoh チームに連絡することもできます。</p></div>`,44)])])}const u=a(r,[["render",n]]);export{m as __pageData,u as default};
